package cn.breezeth.kaleidoscope_grilling;
import com.mojang.serialization.MapCodec;import net.minecraft.core.BlockPos;import net.minecraft.world.item.Item;import net.minecraft.world.level.BlockGetter;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.level.block.CropBlock;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.block.state.StateDefinition;import net.minecraft.world.level.block.state.properties.BlockStateProperties;import net.minecraft.world.level.block.state.properties.IntegerProperty;
public final class HouttuyniaCropBlock extends CropBlock{public static final MapCodec<HouttuyniaCropBlock> CODEC=simpleCodec(HouttuyniaCropBlock::new);public static final IntegerProperty AGE=BlockStateProperties.AGE_2;public HouttuyniaCropBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(AGE,0));}@Override public MapCodec<? extends CropBlock> codec(){return CODEC;}@Override public IntegerProperty getAgeProperty(){return AGE;}@Override public int getMaxAge(){return 2;}@Override protected Item getBaseSeedId(){return ModItems.HOUTTUYNIA.get();}@Override protected boolean mayPlaceOn(BlockState s,BlockGetter l,BlockPos p){return s.is(Blocks.FARMLAND)||s.is(Blocks.SOUL_SAND);}@Override protected void createBlockStateDefinition(StateDefinition.Builder<net.minecraft.world.level.block.Block,BlockState>b){b.add(AGE);}}
